export const specialCases=[
 {id:'sperm',name:'Sperm cell',feature:'Tail',job:'Reach an egg for fertilisation',effect:'movement',options:[['transport','Carries water through a plant'],['movement','Propels the cell towards an egg'],['protein','Makes the nucleus store more proteins']],why:'A tail propels the sperm. Mitochondria in its midpiece provide energy from respiration; these are distinct adaptations.',note:'Tail removal is a hypothetical comparison. Movement is symbolic; no real speed or fluid mechanics is modelled.'},
 {id:'nerve',name:'Nerve cell',feature:'Long axon',job:'Carry electrical impulses over a long distance',effect:'distance',options:[['distance','Connects distant regions without a chain of short cell bodies'],['food','Absorbs more digested food'],['chloroplast','Carries out photosynthesis']],why:'A long axon carries an electrical impulse over a distance. Branched endings connect with other cells.',note:'A moving marker represents an electrical impulse, not a material particle travelling along the axon. Time and distances are symbolic.'},
 {id:'muscle',name:'Muscle cell',feature:'Contractile fibres',job:'Contract to produce movement',effect:'shorten',options:[['sap','Stores cell sap'],['shorten','Enables shortening and force generation'],['dna','Removes the need for genetic material']],why:'Contractile fibres enable muscle cells to shorten and exert force. Many mitochondria support the energy requirement.',note:'Shortening is exaggerated. Molecular sliding and force magnitudes are not simulated; a cell lacking these fibres is a hypothetical comparison.'},
 {id:'root',name:'Root hair cell',feature:'Long membrane projection',job:'Absorb water and mineral ions from soil',effect:'area',options:[['light','Increases light absorption for photosynthesis'],['volume','Makes the surrounding soil contain more minerals'],['area','Provides more membrane surface for absorption']],why:'A root hair increases the membrane surface available for absorption. Underground root hairs do not usually have chloroplasts.',note:'The marker traces a symbolic membrane boundary. It does not measure uptake rate; water and mineral ions enter by different transport mechanisms.'},
 {id:'xylem',name:'Xylem vessel',feature:'Continuous hollow channel',job:'Transport water and mineral ions and support the plant',effect:'channel',options:[['channel','Provides an unobstructed route through connected vessel elements'],['sugar','Synthesises sugar from sunlight'],['living','Makes mature vessel elements contain living cytoplasm']],why:'Mature xylem vessel elements are dead and hollow, with end walls lost. Lignified walls strengthen the vessel and help prevent collapse.',note:'Closed end walls are a counterfactual obstruction. Water flow and lignin placement are symbolic; the mechanism driving flow is not modelled.'},
 {id:'phloem',name:'Phloem sieve tube',feature:'Pores in sieve plates',job:'Transport dissolved sugars between sources and sinks',effect:'sieve',options:[['oxygen','Moves only oxygen out of the leaf'],['sieve','Allows sap to pass between sieve tube elements'],['lignin','Makes every sieve tube element dead and lignified']],why:'Pores in sieve plates connect living sieve tube elements. Companion cells support them, including energy-requiring processes involved in transport.',note:'One source-to-sink path is shown. Translocation can occur in either direction in different tubes; pressure and loading mechanisms are not simulated.'}
];
export const fateCases=[
 {id:'animal',title:'Early animal development',targets:[['nerve','Nerve cell'],['muscle','Muscle cell']],question:'Why are the two developed cells suited to different roles?',answer:'structures',options:[['number','They only differ in how many cells there are'],['structures','They acquire different structures suited to different functions'],['plant','Both become plant cells']],why:'Differentiation produces cells with structures suited to particular functions. Most types of animal cell differentiate early in development.'},
 {id:'plant',title:'A growing plant region',targets:[['root','Root hair cell'],['xylem','Xylem vessel element']],question:'Which statement fits plant differentiation?',answer:'many',options:[['many','Many plant cells retain the ability to differentiate throughout life'],['all','Every mature plant cell can freely become any other type'],['none','Plant cells never differentiate']],why:'Many types of plant cell retain differentiation capacity through life. This does not mean every mature specialised cell can freely switch identity.'},
 {id:'adult',title:'Adult animal tissue repair',targets:[['repair','Repair and replacement']],question:'What is cell division mainly used for in mature animals?',answer:'repair',options:[['repair','Repairing and replacing cells'],['early','Only producing the first embryo'],['switch','Turning every existing specialised cell into another type']],why:'Cell division in mature animals is mainly for repair and replacement. Division increases cell number; differentiation changes cells towards specialised structure and function.'}
];
export const adaptationPosition=(type,adapted,step)=>{const n=Math.max(0,Math.min(6,Math.floor(Number(step)||0)));if(type==='sperm')return adapted?n*16:0;if(type==='nerve')return Math.min(n*43,adapted?258:78);if(type==='muscle')return adapted?n*8:0;if(type==='xylem')return Math.min(n*35,adapted?210:15);if(type==='phloem')return Math.min(n*35,adapted?210:62);return n;};
export const comparedBoth=states=>states?.includes('on')&&states.includes('off');
export function fateReady(t,w){return t.targets.every(([id])=>w.paths?.includes(id));}
